import{_ as a,o as s,c as n,a2 as t}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"QEMU 调试技术","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/qemu-debugging.md","filePath":"zh/troubleshooting/qemu-debugging.md"}'),o={name:"zh/troubleshooting/qemu-debugging.md"};function i(l,e,p,d,r,c){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="qemu-调试技术" tabindex="-1">QEMU 调试技术 <a class="header-anchor" href="#qemu-调试技术" aria-label="Permalink to &quot;QEMU 调试技术&quot;">​</a></h1><h2 id="捕获一切" tabindex="-1">捕获一切 <a class="header-anchor" href="#捕获一切" aria-label="Permalink to &quot;捕获一切&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512 -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -serial file:boot.log -display none \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1</span></span></code></pre></div><p>串口日志<strong>就是</strong>启动叙事——每个子系统一行 <code>OK</code>。</p><h2 id="监视整机-而不只是客户机" tabindex="-1">监视整机，而不只是客户机 <a class="header-anchor" href="#监视整机-而不只是客户机" aria-label="Permalink to &quot;监视整机，而不只是客户机&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-d int,cpu_reset,guest_errors -D qemu.log    (interrupts/resets/errors)</span></span>
<span class="line"><span>-monitor stdio                               (QEMU monitor alongside)</span></span></code></pre></div><h2 id="gdb-接入内核" tabindex="-1">GDB 接入内核 <a class="header-anchor" href="#gdb-接入内核" aria-label="Permalink to &quot;GDB 接入内核&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 ... -s -S        # gdb stub, frozen at reset</span></span>
<span class="line"><span>gdb build/opencube_base.elf          # the pre-strip ELF has symbols</span></span>
<span class="line"><span>(gdb) target remote localhost:1234</span></span>
<span class="line"><span>(gdb) break kmain</span></span>
<span class="line"><span>(gdb) continue</span></span></code></pre></div><p><code>build/opencube_base.elf</code> 正是为此被 <code>make kernel</code> 保留——最终 的 <code>build/opencube.elf</code> 是剥离过的。</p><h2 id="确定性复现" tabindex="-1">确定性复现 <a class="header-anchor" href="#确定性复现" aria-label="Permalink to &quot;确定性复现&quot;">​</a></h2><p>构建是可复现的——同一棵代码树产出逐字节相同的 ELF，因此 你能复现两次的崩溃，两次都是同一批字节。配合 QEMU 自带的 <code>-icount</code> 可让网络测试的时序保持稳定。</p><h2 id="设备矩阵一览" tabindex="-1">设备矩阵一览 <a class="header-anchor" href="#设备矩阵一览" aria-label="Permalink to &quot;设备矩阵一览&quot;">​</a></h2><p>点亮各驱动家族的 QEMU 参数表列在 <a href="./../drivers/storage.html">驱动手册</a>中——精确挂上你正在调试的那个 设备。</p>`,13)])])}const b=a(o,[["render",i]]);export{u as __pageData,b as default};
